#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>

#include <cute/tensor.hpp>

using namespace cute;

// Simple tiled GEMM: C(M,N) = A(M,K) @ B(K,N)
// A is row-major (M,K), stride (K,1)
// B is row-major (K,N), stride (N,1) -> viewed logically as (N,K) with stride (1,N)
// C is row-major (M,N), stride (N,1)
template <class T, int BLK_M, int BLK_N, int BLK_K>
__global__ static void
gemm_device(int M, int N, int K,
            T const* A,
            T const* B,
            T      * C)
{
  // Logical tensors
  Tensor mA = make_tensor(make_gmem_ptr(A), make_shape(M, K), make_stride(K, Int<1>{}));      // (M,K)
  Tensor mB = make_tensor(make_gmem_ptr(B), make_shape(N, K), make_stride(Int<1>{}, N));      // (N,K) view of (K,N) storage
  Tensor mC = make_tensor(make_gmem_ptr(C), make_shape(M, N), make_stride(N, Int<1>{}));      // (M,N)

  auto cta_tiler = make_shape(Int<BLK_M>{}, Int<BLK_N>{}, Int<BLK_K>{});
  auto cta_coord = make_coord(blockIdx.x, blockIdx.y, _);

  Tensor gA = local_tile(mA, cta_tiler, cta_coord, Step<_1, X, _1>{});  // (BLK_M, BLK_K, k)
  Tensor gB = local_tile(mB, cta_tiler, cta_coord, Step< X,_1, _1>{});  // (BLK_N, BLK_K, k)
  Tensor gC = local_tile(mC, cta_tiler, cta_coord, Step<_1,_1,  X>{});  // (BLK_M, BLK_N)

  static_assert(BLK_K % 4 == 0, "BLK_K must be a multiple of 4 for vectorized loads");
  static_assert(BLK_N % 4 == 0, "BLK_N must be a multiple of 4 for vectorized loads");
  static_assert(sizeof(T) == sizeof(float), "Vectorized path assumes 32-bit element type");
  // Shared memory. sA is stored row-major (K contiguous) to match the global
  // memory layout of A, enabling vectorized (float4) global->shared copies.
  // sB uses a padded K-stride (extra SKEW floats per row) to avoid shared-memory
  // bank conflicts that would otherwise occur because BLK_N is an exact multiple
  // of the number of shared-memory banks.
  constexpr int SKEW = 4;
  __shared__ T smemA[BLK_M * BLK_K];
  __shared__ T smemB[(BLK_N + SKEW) * BLK_K];
  Tensor sA = make_tensor(make_smem_ptr(smemA), make_shape(Int<BLK_M>{}, Int<BLK_K>{}), make_stride(Int<BLK_K>{}, Int<1>{}));
  Tensor sB = make_tensor(make_smem_ptr(smemB), make_shape(Int<BLK_N>{}, Int<BLK_K>{}), make_stride(Int<1>{}, Int<BLK_N + SKEW>{}));
  // Thread layout for compute (256 threads, arranged 16x16)
  // Thread layout for compute (256 threads, arranged 16x16). Note: we use a
  // row-major (fast-varying second mode) stride here so that the fastest
  // varying component of threadIdx aligns with the N (column) dimension of
  // gC/sB. Since C and B are both row-major with N contiguous, this makes
  // neighboring threads write/read neighboring N-contiguous elements,
  // dramatically improving global-memory coalescing on the (memory-bound)
  // epilogue write to the very large C output tensor.
  auto tC = make_layout(make_shape(Int<16>{}, Int<16>{}), make_stride(Int<16>{}, Int<1>{}));
  Tensor tCsA = local_partition(sA, tC, threadIdx.x, Step<_1, X>{});  // (BLK_M/16, BLK_K)
  Tensor tCsB = local_partition(sB, tC, threadIdx.x, Step< X,_1>{});  // (BLK_N/16, BLK_K)
  Tensor tCgC = local_partition(gC, tC, threadIdx.x, Step<_1,_1>{});  // (BLK_M/16, BLK_N/16)
  Tensor tCrC = make_tensor_like(tCgC);
  clear(tCrC);
  // Vectorized load configuration for A: each row of the tile (BLK_K contiguous
  // floats in global memory) is split into BLK_K/4 float4 chunks. 256 threads
  // are arranged as (rows) x (col-groups) so that each thread's inner-most
  // access is a contiguous 128-bit load, matching the row-major sA layout above.
  constexpr int A_COLGROUPS   = BLK_K / 4;
  constexpr int A_THREADS_ROW = 256 / A_COLGROUPS;
  constexpr int A_ROW_ITERS   = BLK_M / A_THREADS_ROW;

  int aRowThread = threadIdx.x / A_COLGROUPS;
  int aColGroup  = threadIdx.x % A_COLGROUPS;

  // Vectorized load configuration for B: each K-row of the tile has BLK_N
  // contiguous floats in global memory (B is stored row-major as (K,N)).
  constexpr int B_COLGROUPS   = BLK_N / 4;
  constexpr int B_THREADS_ROW = 256 / B_COLGROUPS;
  constexpr int B_ROW_ITERS   = BLK_K / B_THREADS_ROW;

  int bRowThread = threadIdx.x / B_COLGROUPS;
  int bColGroup  = threadIdx.x % B_COLGROUPS;
  int K_TILE_MAX = size<2>(gA);
  for (int k_tile = 0; k_tile < K_TILE_MAX; ++k_tile) {
    // Vectorized copy of the A tile (row-major, K contiguous) into sA (row-major).
    const T* gA_base = A + (size_t)blockIdx.x * BLK_M * K + (size_t)k_tile * BLK_K;
    #pragma unroll
    for (int i = 0; i < A_ROW_ITERS; ++i) {
      int row = aRowThread + i * A_THREADS_ROW;
      const float4* src = reinterpret_cast<const float4*>(gA_base + (size_t)row * K) + aColGroup;
      float4* dst = reinterpret_cast<float4*>(smemA + row * BLK_K) + aColGroup;
      *dst = *src;
    }
    // Vectorized copy of the B tile (row-major, N contiguous) into sB (N contiguous).
    const T* gB_base = B + (size_t)k_tile * BLK_K * N + (size_t)blockIdx.y * BLK_N;
    #pragma unroll
    for (int i = 0; i < B_ROW_ITERS; ++i) {
      int krow = bRowThread + i * B_THREADS_ROW;
      const float4* src = reinterpret_cast<const float4*>(gB_base + (size_t)krow * N) + bColGroup;
      float4* dst = reinterpret_cast<float4*>(smemB + krow * (BLK_N + SKEW)) + bColGroup;
      *dst = *src;
    }
    __syncthreads();
    gemm(tCsA, tCsB, tCrC);
    __syncthreads();
  }
  // Epilogue: write result
  axpby(T(1), tCrC, T(0), tCgC);
}

torch::Tensor cute_gemm_forward(torch::Tensor A, torch::Tensor B) {
  TORCH_CHECK(A.is_cuda() && B.is_cuda(), "A and B must be CUDA tensors");
  TORCH_CHECK(A.dim() == 2 && B.dim() == 2, "A and B must be 2D");
  TORCH_CHECK(A.scalar_type() == at::kFloat && B.scalar_type() == at::kFloat,
              "Expect float32 tensors");

  auto A_c = A.contiguous();
  auto B_c = B.contiguous();

  int M = (int)A_c.size(0);
  int K = (int)A_c.size(1);
  int N = (int)B_c.size(1);
  TORCH_CHECK((int)B_c.size(0) == K, "Inner dimensions of A and B must match");

  // For this workload M is very large while N and K are small (tall-and-skinny).
  // Tile only over the large M dimension and keep the small N/K dimensions
  // fully resident within a single CTA tile to maximize reuse and avoid
  // falling back to a generic matmul for shapes that don't fit a square tiling.
  constexpr int BLK_M = 128;
  constexpr int BLK_N = 64;
  constexpr int BLK_K = 32;

  auto C = torch::empty({M, N}, A.options());

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

  if (M % BLK_M == 0 && N % BLK_N == 0 && K % BLK_K == 0) {
    dim3 dimBlock(256);
    dim3 dimGrid(M / BLK_M, N / BLK_N);

    gemm_device<float, BLK_M, BLK_N, BLK_K><<<dimGrid, dimBlock, 0, stream>>>(
        M, N, K,
        A_c.data_ptr<float>(),
        B_c.data_ptr<float>(),
        C.data_ptr<float>()
    );

    auto err = cudaGetLastError();
    TORCH_CHECK(err == cudaSuccess, "CUTE gemm launch failed: ", cudaGetErrorString(err));
  } else {
    // Fallback for shapes that don't fit the tiling assumptions
    C = at::matmul(A_c, B_c);
  }

  return C;
}
"""

cute_gemm_ext = load_inline(
    name="cute_gemm_tall_skinny_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["cute_gemm_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include",
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Simple model that performs a single matrix multiplication (C = A * B)
    using a custom CUTE-based tiled GEMM kernel, optimized for the case
    where the contraction dimension K is small relative to M and N.
    """
